const items=window.NUZHA_MENU||[],grid=document.querySelector("#fullMenuGrid"),filters=document.querySelector("#menuPageFilters");
let lang=localStorage.getItem("nuzha-lang")||"en",filter="all";
const labels={en:{all:"All",feasts:"Feasts",rice:"Rice",seafood:"Seafood",bbq:"BBQ",salads:"Salads & mezze",kitchen:"From the kitchen"},ar:{all:"الكل",feasts:"الولائم",rice:"الأرز",seafood:"المأكولات البحرية",bbq:"المشويات",salads:"السلطات والمقبلات",kitchen:"من المطبخ"}};
function applyLanguage(){document.documentElement.lang=lang;document.documentElement.dir=lang==="ar"?"rtl":"ltr";langBtn.textContent=lang==="en"?"العربية":"English";document.querySelectorAll("[data-en]").forEach(el=>el.textContent=el.dataset[lang]);render()}
function render(){const cats=["all",...new Set(items.map(x=>x.category))];filters.innerHTML=cats.map(c=>`<button class="filter-btn ${c===filter?'active':''}" data-filter="${c}">${labels[lang][c]||c}</button>`).join("");grid.innerHTML=items.filter(x=>filter==="all"||x.category===filter).map(x=>`<article class="full-menu-card"><img src="${x.image}" alt="${lang==='ar'?x.nameAr:x.nameEn}" loading="lazy"><div class="full-menu-copy"><small>${labels[lang][x.category]}</small><div class="full-menu-title"><h2>${lang==='ar'?x.nameAr:x.nameEn}</h2><strong><span>${x.price}</span> <b>${lang==='ar'?'ر.س':'SAR'}</b></strong></div><p>${lang==='ar'?x.descAr:x.descEn}</p></div></article>`).join("");filters.querySelectorAll("button").forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()})}
langBtn.onclick=()=>{lang=lang==="en"?"ar":"en";localStorage.setItem("nuzha-lang",lang);applyLanguage()};themeBtn.onclick=()=>{const order=[null,"theme-night","theme-rose"],active=document.body.classList.contains("theme-night")?1:document.body.classList.contains("theme-rose")?2:0,next=order[(active+1)%3];document.body.classList.remove("theme-night","theme-rose");if(next)document.body.classList.add(next)};document.querySelector(".menu-toggle").onclick=e=>{const n=document.querySelector(".site-header nav");n.classList.toggle("open");e.currentTarget.setAttribute("aria-expanded",n.classList.contains("open"))};applyLanguage();
